const ROWS = 6, COLS = 7;
let board, currentPlayer, gameActive, scores;

function init() {
  board = Array.from({length: ROWS}, () => Array(COLS).fill(null));
  currentPlayer = 'red';
  gameActive = true;
  scores = { red: 0, yellow: 0, draw: 0 };
  render();
  updateStatus();
}

function render() {
  const boardEl = document.getElementById('board');
  boardEl.innerHTML = '';
  for (let c = 0; c < COLS; c++) {
    const col = document.createElement('div');
    col.className = 'col';
    col.dataset.col = c;
    for (let r = ROWS-1; r >= 0; r--) {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.dataset.row = r;
      cell.dataset.col = c;
      if (board[r][c] === 'red') cell.classList.add('red');
      else if (board[r][c] === 'yellow') cell.classList.add('yellow');
      col.appendChild(cell);
    }
    col.addEventListener('click', () => handleClick(c));
    boardEl.appendChild(col);
  }
}

function handleClick(col) {
  if (!gameActive) return;
  for (let r = 0; r < ROWS; r++) {
    if (!board[r][col]) {
      board[r][col] = currentPlayer;
      render();
      if (checkWin(r, col)) {
        gameActive = false;
        scores[currentPlayer]++;
        updateScores();
        highlightWins(r, col);
        document.getElementById('status').textContent = currentPlayer.charAt(0).toUpperCase() + currentPlayer.slice(1) + ' wins!';
        Array.from(document.querySelectorAll('.col')).forEach(c => c.classList.add('game-over'));
        return;
      }
      if (board.every(row => row.every(cell => cell !== null))) {
        gameActive = false;
        scores.draw++;
        updateScores();
        document.getElementById('status').textContent = "It's a draw!";
        Array.from(document.querySelectorAll('.col')).forEach(c => c.classList.add('game-over'));
        return;
      }
      currentPlayer = currentPlayer === 'red' ? 'yellow' : 'red';
      updateStatus();
      return;
