let transactions = [];
let currentFilter = 'all';
let currentPeriod = 'month';

function loadData() {
  try {
    const saved = localStorage.getItem('expense-tracker-data');
    if (saved) transactions = JSON.parse(saved);
  } catch {}
}

function saveData() {
  localStorage.setItem('expense-tracker-data', JSON.stringify(transactions));
}

function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

function escapeHTML(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function isInPeriod(tx, period) {
  const now = new Date();
  const txDate = new Date(tx.date);
  if (period === 'week') {
    const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    return txDate >= weekAgo;
  }
  if (period === 'month') {
    return txDate.getMonth() === now.getMonth() && txDate.getFullYear() === now.getFullYear();
  }
  return true;
}

function addTransaction() {
  const type = document.getElementById('txType').value;
  const desc = document.getElementById('txDesc').value.trim();
  const amount = parseFloat(document.getElementById('txAmount').value);
  const category = document.getElementById('txCategory').value;

  if (!desc || !amount || amount <= 0) { alert('Please fill in all fields'); return; }

  transactions.unshift({
    id: generateId(),
    type,
    description: desc,
    amount,
    category,
    date: new Date().toISOString(),
  });

  saveData();
  closeModal();
  document.getElementById('txDesc').value = '';
  document.getElementById('txAmount').value = '';
  render();
}

function deleteTransaction(id) {
  transactions = transactions.filter(t => t.id !== id);
  saveData();
  render();
}

function setFilter(filter) {
  currentFilter = filter;
  document.querySelectorAll('.filter-btn[data-filter]').forEach(b => b.classList.toggle('active', b.dataset.filter === filter));
  render();
}

function setPeriod(period) {
  currentPeriod = period;
  document.querySelectorAll('.filter-btn[data-period]').forEach(b => b.classList.toggle('active', b.dataset.period === period));
  render();
}

function getFiltered() {
  return transactions.filter(tx => {
    if (currentFilter !== 'all' && tx.type !== currentFilter) return false;
    if (!isInPeriod(tx, currentPeriod)) return false;
    return true;
  });
}
