}

function getFileIcon(name, type) {
  if (type === 'folder') return '📁';
  const ext = name.split('.').pop().toLowerCase();
  if (FILE_TYPES.images.includes(ext)) return '🖼️';
  if (ext === 'pdf') return '📕';
  if (ext === 'md') return '📝';
  if (ext === 'json' || ext === 'xml') return '📋';
  if (FILE_TYPES.code.includes(ext)) return '📜';
  if (FILE_TYPES.archives.includes(ext)) return '🗜️';
  if (FILE_TYPES.media.some(m => m === ext)) return '🎵';
  if (ext === 'csv') return '📊';
  if (ext === 'html') return '🌐';
  return '📄';
}

