    return `<div class="rule-card"><span class="rule-type">${typeLabels[r.type]||r.type}</span><span class="rule-msg">${r.value?escapeHTML(r.value)+' — ':''}${escapeHTML(r.message)}</span><button class="rule-del" onclick="removeRule(${r.id})">✕</button></div>`;
