function validateInput(){
  const val=document.getElementById('testInput').value;
  const matchVal=document.getElementById('matchField').value;
  const results=document.getElementById('validationResults');
  const input=document.getElementById('testInput');
  if(!rules.length){results.innerHTML='';input.className='test-input';return}
  let allPass=true,html='';
  for(const r of rules){
    let pass=true,msg=r.message;
    switch(r.type){
      case 'required':pass=val.trim().length>0;break;
      case 'email':pass=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);break;
      case 'minLength':pass=val.length>=parseInt(r.value||1);msg=r.message||`Must be at least ${r.value} characters`;break;
      case 'maxLength':pass=val.length<=parseInt(r.value||999);msg=r.message||`Must be at most ${r.value} characters`;break;
      case 'pattern':try{pass=new RegExp(r.value).test(val)}catch(e){pass=false;msg='Invalid regex pattern'}break;
      case 'match':pass=val===matchVal;msg=r.message||'Fields do not match';break;
    }
    if(!pass)allPass=false;
    html+=`<div class="val-result ${pass?'pass':'fail'}">${pass?'✓':'✗'} ${escapeHTML(msg)}</div>`;
  }
  results.innerHTML=html;
  input.className='test-input '+(allPass?'valid':rules.length?'invalid':'');
}

