const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
let originalImage = null;
let currentFilter = 'none';
let historyStack = [];
let redoStack = [];
let imageLoaded = false;

function loadImage(e) {
  const file = e.target.files[0];
  if (!file) return;
  const img = new Image();
  img.onload = () => {
    originalImage = img;
    canvas.width = Math.min(img.width, 800);
    canvas.height = Math.min(img.height, 600);
    imageLoaded = true;
    document.getElementById('dropArea').style.display = 'none';
    canvas.style.display = 'block';
    document.getElementById('historyBar').style.display = 'flex';
    document.getElementById('imageInfo').textContent = `${img.width} × ${img.height}px · ${file.name}`;
    historyStack = []; redoStack = [];
    saveState();
    applyFilters();
  };
  img.src = URL.createObjectURL(file);
  e.target.value = '';
}

function saveState() {
  historyStack.push(canvas.toDataURL());
  if (historyStack.length > 20) historyStack.shift();
  redoStack = [];
}

function undo() {
  if (historyStack.length <= 1) return;
  redoStack.push(historyStack.pop());
  const prev = historyStack[historyStack.length - 1];
  const img = new Image();
  img.onload = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0);
  };
  img.src = prev;
}

function redo() {
  if (redoStack.length === 0) return;
  const next = redoStack.pop();
  historyStack.push(next);
  const img = new Image();
  img.onload = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0);
  };
  img.src = next;
}

function applyFilters() {
  if (!originalImage) return;
  const brightness = parseInt(document.getElementById('brightness').value);
  const contrast = parseInt(document.getElementById('contrast').value);
  const saturation = parseInt(document.getElementById('saturation').value);
  const blur = parseFloat(document.getElementById('blur').value);

  document.getElementById('brightnessVal').textContent = brightness;
  document.getElementById('contrastVal').textContent = contrast;
  document.getElementById('saturationVal').textContent = saturation;
  document.getElementById('blurVal').textContent = blur;

  // Draw original
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.drawImage(originalImage, 0, 0, canvas.width, canvas.height);

  // Get image data
  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = imageData.data;

  // Apply adjustments pixel by pixel
  for (let i = 0; i < data.length; i += 4) {
    let r = data[i], g = data[i+1], b = data[i+2];

    // Brightness
    if (brightness !== 0) {
      const bFactor = 1 + brightness / 100;
      r *= bFactor; g *= bFactor; b *= bFactor;
    }

    // Contrast
    if (contrast !== 0) {
      const factor = (259 * (contrast + 255)) / (255 * (259 - contrast));
      r = factor * (r - 128) + 128;
      g = factor * (g - 128) + 128;
      b = factor * (b - 128) + 128;
    }

    // Saturation
    if (saturation !== 0) {
      const gray = 0.2989 * r + 0.5870 * g + 0.1140 * b;
      const sFactor = 1 + saturation / 100;
      r = gray + sFactor * (r - gray);
      g = gray + sFactor * (g - gray);
      b = gray + sFactor * (b - gray);
    }

    // Filter presets
    if (currentFilter === 'grayscale') {
      const gray = 0.2989 * r + 0.5870 * g + 0.1140 * b;
      r = g = b = gray;
    } else if (currentFilter === 'sepia') {
      r = r * 0.393 + g * 0.769 + b * 0.189;
      g = r * 0.349 + g * 0.686 + b * 0.168;
      b = r * 0.272 + g * 0.534 + b * 0.131;
    } else if (currentFilter === 'invert') {
      r = 255 - r; g = 255 - g; b = 255 - b;
    } else if (currentFilter === 'warm') {
      r *= 1.15; b *= 0.85;
    } else if (currentFilter === 'cool') {
      b *= 1.15; r *= 0.85;
    } else if (currentFilter === 'vintage') {
      r = r * 0.9 + 30; g = g * 0.85 + 15; b = b * 0.75;
    } else if (currentFilter === 'dramatic') {
      r = r > 128 ? Math.min(255, r * 1.3) : r * 0.7;
      g = g > 128 ? Math.min(255, g * 1.3) : g * 0.7;
      b = b > 128 ? Math.min(255, b * 1.3) : b * 0.7;
    }

    data[i] = Math.max(0, Math.min(255, r));
    data[i+1] = Math.max(0, Math.min(255, g));
    data[i+2] = Math.max(0, Math.min(255, b));
  }

  ctx.putImageData(imageData, 0, 0);

  // Apply blur as CSS filter on top
  canvas.style.filter = blur > 0 ? `blur(${blur}px)` : 'none';
}

function setFilter(filter) {
  currentFilter = filter;
  document.querySelectorAll('.filter-btn').forEach(b => b.classList.toggle('active', b.dataset.filter === filter));
  applyFilters();
}

function rotateImage(deg) {
  if (!originalImage) return;
  const tempCanvas = document.createElement('canvas');
  const tempCtx = tempCanvas.getContext('2d');
  tempCanvas.width = canvas.height;
  tempCanvas.height = canvas.width;
  tempCtx.translate(tempCanvas.width / 2, tempCanvas.height / 2);
  tempCtx.rotate(deg * Math.PI / 180);
  tempCtx.drawImage(canvas, -canvas.width / 2, -canvas.height / 2);

  canvas.width = tempCanvas.width;
  canvas.height = tempCanvas.height;
