function parseExpression(expr){
  // Convert word forms to symbols — NOT to JS operators
  let s=expr
    .replace(/\s+/g,' ').trim()
    .replace(/AND\b/gi,' & ')
    .replace(/OR\b/gi,' | ')
    .replace(/NOT\b/gi,' ! ')
    .replace(/XOR\b/gi,' ^ ')
    .replace(/XNOR\b/gi,' ↔ ')
    .replace(/IMPLIES\b/gi,' → ')
    .replace(/(\w+)\s+NAND\s+(\w+)/gi,'!($1 & $2)')
    .replace(/(\w+)\s+NOR\s+(\w+)/gi,'!($1 | $2)')
    .replace(/\s+/g,' ').trim();
  const vars=[...new Set(s.match(/[A-Z]/g)||[])].sort();
  return{expr:s,vars};
}

// Safe recursive descent boolean expression parser (no eval/Function)
function evaluate(expr,vals){
  let pos=0;
  function peek(){while(pos<expr.length&&expr[pos]===' ')pos++;return pos<expr.length?expr[pos]:''}
  function eat(ch){if(peek()===ch){pos++;return true}return false}

  // Precedence (lowest to highest): ↔ → | ^ & !
  function parseEquiv(){
    let left=parseImplies();
    while(peek()==='↔'){pos++;left=left===parseImplies()}
    return left;
  }
  function parseImplies(){
    let left=parseOr();
    if(peek()==='→'){pos++;const right=parseImplies();left=!left||right}
    return left;
  }
  function parseOr(){
    let left=parseXor();
    while(peek()==='|'){pos++;left=left||parseXor()}
    return left;
  }
  function parseXor(){
    let left=parseAnd();
    while(peek()==='^'){pos++;left=left!==parseAnd()}
    return left;
  }
  function parseAnd(){
    let left=parseNot();
    while(peek()==='&'){pos++;left=left&&parseNot()}
    return left;
  }
  function parseNot(){
    if(eat('!'))return !parseNot();
    if(eat('(')){const val=parseEquiv();if(!eat(')'))return null;return val}
    const ch=peek();
    if(ch>='A'&&ch<='Z'){pos++;return!!vals[ch]}
    if(ch==='0'){pos++;return false}
    if(ch==='1'){pos++;return true}
    return null;
  }

  try{
    const result=parseEquiv();
    if(peek())return null;
    return result;
  }catch(e){return null}
}

function generate(){
  const input=document.getElementById('exprInput').value;
  const{expr,vars}=parseExpression(input);
  document.getElementById('varDisplay').textContent=`Variables: ${vars.join(', ')||'none'}`;

  if(vars.length===0){document.getElementById('tableContainer').innerHTML='<div class="error">No variables found. Use A, B, C, etc.</div>';document.getElementById('stepsDisplay').textContent='';return}
  if(vars.length>6){document.getElementById('tableContainer').innerHTML=`<div class="error">Too many variables (${vars.length}). Max 6.</div>`;return}

  const rows=1<<vars.length;
  let html='<table><tr>';
  vars.forEach(v=>html+=`<th>${v}</th>`);
  html+=`<th style="background:rgba(0,217,255,0.05);color:#00d9ff">Result</th></tr>`;
  let trueCount=0;

  for(let i=0;i<rows;i++){
    const vals={};
    vars.forEach((v,j)=>{vals[v]=!!((i>>(vars.length-1-j))&1)});
    const result=evaluate(expr,vals);
    if(result===null){html=`<div class="error">❌ Invalid expression: ${input}</div>`;break}
    if(result)trueCount++;
    html+='<tr>';
    vars.forEach(v=>{html+=`<td class="${vals[v]?'high':'low'}">${vals[v]?1:0}</td>`});
    html+=`<td class="${result?'high':'low'} result-col">${result?1:0}</td></tr>`;
  }
  html+='</table>';
  document.getElementById('tableContainer').innerHTML=html;
  document.getElementById('stepsDisplay').innerHTML=
    `Rows: ${rows} · True: ${trueCount} · False: ${rows-trueCount} · Expression: <code>${expr}</code> · Variables: ${vars.join(', ')}`;
  saveToStorage();
}

function loadPreset(expr){document.getElementById('exprInput').value=expr;generate()}

function saveToStorage(){try{localStorage.setItem('truth_table_expr',document.getElementById('exprInput').value)}catch(e){}}
function loadFromStorage(){try{const v=localStorage.getItem('truth_table_expr');if(v){document.getElementById('exprInput').value=v;return true}}catch(e){}return false}

if(!loadFromStorage())generate();
